#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static size_t ilen = 0, ipos = 0;

static inline int gc() {
    if (ipos == ilen) {
        ilen = fread(ibuf, 1, sizeof ibuf, stdin);
        ipos = 0;
        if (ilen == 0) return -1;
    }
    return ibuf[ipos++];
}

static long long readInt() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    bool neg = c == '-';
    if (neg) c = gc();
    long long v = 0;
    while (c >= '0' && c <= '9') {
        v = v * 10 + (c - '0');
        c = gc();
    }
    return neg ? -v : v;
}

static string readToken() {
    int c = gc();
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = gc();
    string s;
    while (c > ' ') {
        s.push_back((char)c);
        c = gc();
    }
    return s;
}

int main() {
    long long p = readInt(), q = readInt();
    string s = readToken();
    // dp over prefixes, keeping the last three values: d1 = dp[end-1], d2 = dp[end-2], d3 = dp[end-3].
    long long d3 = 0, d2 = 0, d1 = 0;
    for (size_t end = 1; end <= s.size(); end++) {
        long long value = d1;
        if (end >= 2 && s[end - 2] != s[end - 1]) value = max(value, d2 + q);
        if (end >= 3 && s[end - 3] == '0' && s[end - 2] == '0' && s[end - 1] == '0') value = max(value, d3 + p);
        d3 = d2;
        d2 = d1;
        d1 = value;
    }
    printf("%lld\n", d1);
}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        long p = nextLong(), q = nextLong();
        String s = next();
        long d3 = 0, d2 = 0, d1 = 0;
        for (int end = 1; end <= s.length(); end++) {
            long value = d1;
            if (end >= 2 && s.charAt(end - 2) != s.charAt(end - 1)) value = Math.max(value, d2 + q);
            if (end >= 3 && s.charAt(end - 3) == '0' && s.charAt(end - 2) == '0' && s.charAt(end - 1) == '0')
                value = Math.max(value, d3 + p);
            d3 = d2;
            d2 = d1;
            d1 = value;
        }
        System.out.println(d1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	p, q := nextInt(), nextInt()
	s := token()
	d3, d2, d1 := 0, 0, 0
	for end := 1; end <= len(s); end++ {
		value := d1
		if end >= 2 && s[end-2] != s[end-1] {
			value = max(value, d2+q)
		}
		if end >= 3 && s[end-3] == '0' && s[end-2] == '0' && s[end-1] == '0' {
			value = max(value, d3+p)
		}
		d3, d2, d1 = d2, d1, value
	}
	fmt.Println(d1)
}
